#include <iostream>
#include <string>

int main()
{
    std::string first{};
    std::string last{};
    std::cin >> first >> last;

    std::string username{};
    username += first[0];
    username += last;
    username += std::to_string(first.length() + last.length());

    std::cout << username << '\n';
    return 0;
}
